import{_ as e,o as a,c as i,ag as s}from"./chunks/framework.CHxxV8OH.js";const u=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{"prev":false,"next":{"text":"Installation","link":"/installation"}},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md","lastUpdated":1775890242000}'),n={name:"getting-started.md"};function o(l,t,r,d,h,g){return a(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>Welcome to Agent Studio. This guide walks you through installing, setting up your first workspace, and building your first agent.</p><h2 id="what-you-ll-need" tabindex="-1">What You&#39;ll Need <a class="header-anchor" href="#what-you-ll-need" aria-label="Permalink to &quot;What You&#39;ll Need&quot;">​</a></h2><ul><li><strong>VS Code</strong> (1.85 or later): <a href="https://code.visualstudio.com" target="_blank" rel="noreferrer">Download</a></li><li><strong>A workspace folder</strong>: Any empty or existing VS Code workspace</li><li><strong>5 minutes</strong>: That&#39;s all it takes to get your first agent running</li></ul><p>You don&#39;t need Node.js, Python, or any other runtime unless your agents themselves use them.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><ol><li>Open VS Code</li><li>Go to Extensions (Cmd/Ctrl+Shift+X)</li><li>Search for <strong>&quot;Agent Studio&quot;</strong></li><li>Click <strong>Install</strong></li></ol><p>Agent Studio will appear in your sidebar immediately. No reload required.</p><h2 id="open-agent-studio" tabindex="-1">Open Agent Studio <a class="header-anchor" href="#open-agent-studio" aria-label="Permalink to &quot;Open Agent Studio&quot;">​</a></h2><p>Click the <strong>Agent Studio icon</strong> in the VS Code activity bar (left sidebar). The main panel will appear showing:</p><ul><li><strong>Quick Actions</strong> at the top</li><li><strong>Agents</strong> tab (empty for now)</li><li><strong>Workflows</strong> tab</li><li><strong>Capabilities</strong> tab</li><li><strong>Templates</strong> tab</li></ul><h2 id="create-your-first-agent" tabindex="-1">Create Your First Agent <a class="header-anchor" href="#create-your-first-agent" aria-label="Permalink to &quot;Create Your First Agent&quot;">​</a></h2><ol><li>Click <strong>&quot;New Agent&quot;</strong> in the sidebar</li><li>Fill in the form: <ul><li><strong>Name</strong>: <code>DataExplorer</code></li><li><strong>Emoji</strong>: 📊</li><li><strong>Role</strong>: &quot;Analyzes datasets and generates insights&quot;</li></ul></li><li>Click <strong>Create</strong></li></ol><p>Agent Studio will:</p><ul><li>Create a new <code>.agent.md</code> file in your workspace</li><li>Open the Agent Builder editor</li><li>Add it to your sidebar</li></ul><h2 id="add-instructions" tabindex="-1">Add Instructions <a class="header-anchor" href="#add-instructions" aria-label="Permalink to &quot;Add Instructions&quot;">​</a></h2><p>The <strong>Instructions</strong> tab is where you describe how your agent should behave.</p><p>Click the markdown editor and type:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># DataExplorer Agent</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">You are a data analysis expert. Your role is to:</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Load and examine CSV files</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Generate statistical summaries</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Create visualizations</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Identify outliers and anomalies</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Make data-driven recommendations</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">When you receive a file, first describe what you observe,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">then ask clarifying questions before diving into analysis.</span></span></code></pre></div><p>As you type, you&#39;ll see a live preview in the sidebar. The <code>.agent.md</code> file updates in real-time.</p><h2 id="add-capabilities" tabindex="-1">Add Capabilities <a class="header-anchor" href="#add-capabilities" aria-label="Permalink to &quot;Add Capabilities&quot;">​</a></h2><p>Your agent needs tools to do useful work.</p><ol><li>Click the <strong>Capabilities</strong> tab in the Agent Builder</li><li>In the search box, type <code>read</code> to find file reading capabilities</li><li>Click <strong><code>file_read</code></strong> to add it</li><li>Add a few more: <ul><li><code>csv_parse</code></li><li><code>compute_stats</code></li><li><code>plot_chart</code></li></ul></li></ol><p>These are example capabilities. In your real workspace, you&#39;ll see the tools you actually have registered. For now, Agent Studio lets you add any name; you&#39;ll wire up real implementations later.</p><h2 id="set-up-handoffs-optional" tabindex="-1">Set Up Handoffs (Optional) <a class="header-anchor" href="#set-up-handoffs-optional" aria-label="Permalink to &quot;Set Up Handoffs (Optional)&quot;">​</a></h2><p>If you have another agent in your workspace, you can define which agents this one can delegate to.</p><ol><li>Click the <strong>Handoffs</strong> tab</li><li>Search for another agent</li><li>Click to add it as a delegation target</li><li>Set constraints: <ul><li><strong>Requires approval</strong>: Check if a human should approve before delegating</li><li><strong>Max retries</strong>: How many times to retry if it fails</li><li><strong>Timeout</strong>: How long to wait before giving up</li></ul></li></ol><p>For your first agent, you can skip this step.</p><h2 id="save-your-agent" tabindex="-1">Save Your Agent <a class="header-anchor" href="#save-your-agent" aria-label="Permalink to &quot;Save Your Agent&quot;">​</a></h2><p>Click <strong>Save</strong> (Cmd/Ctrl+S) or it will auto-save as you edit.</p><p>Your agent is now saved as <code>.agent.md</code> in your workspace root. You can:</p><ul><li>Commit it to git</li><li>Share it with your team</li><li>Edit it in any text editor</li></ul><h2 id="test-your-agent-in-vs-code-chat" tabindex="-1">Test Your Agent in VS Code Chat <a class="header-anchor" href="#test-your-agent-in-vs-code-chat" aria-label="Permalink to &quot;Test Your Agent in VS Code Chat&quot;">​</a></h2><ol><li>Go to the <strong>VS Code Chat</strong> pane (Cmd/Ctrl+Alt+I)</li><li>Start a new chat</li><li>Click the <strong>Agent Studio</strong> icon in the chat header</li><li>Select your <code>DataExplorer</code> agent</li><li>Ask it a question or give it a task</li></ol><p>The agent&#39;s instructions and capabilities are automatically copied into the chat context. Your model will use this to understand its role and constraints.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><p>Congratulations! You&#39;ve created your first agent. Now you&#39;re ready to:</p><ul><li><strong><a href="./visual-dashboard">Explore the Dashboard</a></strong>: Learn all the features available</li><li><strong><a href="./creating-agents">Create Multiple Agents</a></strong>: Build a multi-agent team</li><li><strong><a href="./workflows">Build Workflows</a></strong>: Chain agents together for complex tasks</li><li><strong><a href="./tools-and-skills">Register Tools</a></strong>: Connect your own APIs and functions</li></ul><p>You can also browse <a href="./why-agent-studio">Why Agent Studio</a> to understand the philosophy behind the tool.</p><hr><p><strong><a href="/agent-studio/">← Back</a></strong> | <strong><a href="./installation">Read Installation →</a></strong></p>`,41)])])}const c=e(n,[["render",o]]);export{u as __pageData,c as default};
